// ============================================================================
// Refine Slide: Check request. A sales person prompt-edits ONE slide of a deck (Human-in-the-Loop AI refinement):
// body {deckId, slideIndex, instruction} from the CSTAM interface. slideIndex = the slide's place in the studio's editor,
// 0-based, the same index the studio's own Regenerate button sends (0 = title slide; the last slide is the closing one:
// both are fixed). A bad request is answered 400 here, before any agent or studio call.
// ============================================================================
// where the two services are, as seen from inside n8n
const REGENERATE_URL = 'http://127.0.0.1:5678/webhook/rfp/regenerate';   // the deck agents' "RFP 60 Regenerate one slide", same n8n (not localhost: IPv6 first)
const STUDIO_URL = 'http://host.docker.internal:8091';                   // the proposal studio (Main's Config STUDIO_URL)
const MIN_CHARS = 3, MAX_CHARS = 200;                                     // the agents keep at most 200 characters of an instruction

const raw = $input.first().json.body;
let req = raw;
if (typeof raw === 'string') { try { req = JSON.parse(raw); } catch (e) { req = null; } }   // sent as text/plain
if (!req || typeof req !== 'object' || Array.isArray(req)) req = {};
const bad = message => [{ json: { _ok: false, statusCode: 400, body: { status: 'error', message } } }];

const deckId = typeof req.deckId === 'string' ? req.deckId.trim() : '';
if (!/^[A-Za-z0-9_-]{1,64}$/.test(deckId)) return bad('deckId is missing or invalid (letters, digits, _ and -, at most 64).');
const n = typeof req.slideIndex === 'string' && /^\s*\d+\s*$/.test(req.slideIndex) ? Number(req.slideIndex) : req.slideIndex;
if (n === 0) return bad('The title slide cannot be refined.');
if (!Number.isInteger(n) || n < 1 || n > 999) return bad('slideIndex must be a whole number from 1 (0 is the title slide).');
const instruction = typeof req.instruction === 'string' ? req.instruction.replace(/\s+/g, ' ').trim() : '';
if (instruction.length < MIN_CHARS) return bad(`Write an instruction of at least ${MIN_CHARS} characters.`);
if (instruction.length > MAX_CHARS) return bad(`The instruction is too long (${instruction.length} characters, at most ${MAX_CHARS}).`);

return [{ json: { _ok: true, deckId, slideIndex: n, instruction, regenerateUrl: REGENERATE_URL, studioUrl: STUDIO_URL,
  saveUrl: `${STUDIO_URL}/api/decks/${deckId}/slides/${n}`, deckUrl: `${STUDIO_URL}/api/save/${deckId}` } }];

// ============================================================================
// Refine Slide: Check slide. The answer of the deck agents' regenerate webhook (full HTTP response, never thrown):
//   200 = ONE slide spec: the agent that owns the slide ran its stage again with the instruction (code still checks the
//         facts), or the CURRENT slide with a last warning "... : slide inchangée" (too slow, no slide, invalid answer);
//   400 = a fixed slide or a bad request, 404 = a deck the agents' registry does not know, other = a failure.
// Only a new slide goes on to the studio: the current one, or a slide the agent could not make (placeholders), is never
// saved over the person's slide. The spec's own warnings are kept (the editor shows them).
// ============================================================================
const req = $('Check request').first().json;
const r = $input.first().json || {};
const fail = (statusCode, message) => [{ json: { _ok: false, statusCode, body: { status: 'error', message } } }];

if (r.error) {                                                   // no HTTP answer at all (On Error: continue)
  const m = String((r.error && (r.error.message || r.error.description)) || r.error);
  return /timeout|timed out|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(m) ? fail(504, 'The deck agents took too long to answer (over 90 s). Try again.')
    : fail(502, 'The deck agents cannot be reached: is "RFP 60 Regenerate one slide" published in this n8n?');
}
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON: handled below */ } }
const code = Number(r.statusCode) || 0;
const said = body && typeof body === 'object' && typeof body.message === 'string' ? body.message : '';

if (code === 404 && /unknown deck/i.test(said)) return fail(404, 'This deck was made before the agents ran in n8n: generate it again to refine it.');
if (code === 404) return fail(502, 'The agents\' regenerate webhook is not active: publish "RFP 60 Regenerate one slide" in n8n, then restart n8n.');
if (code === 401 || code === 403) return fail(502, 'The agents\' regenerate webhook refused the key of the "RegenWebhook" credential.');
if (code === 400 && /cannot be regenerated/i.test(said)) {
  return fail(400, 'This slide cannot be refined: only the content slides written by the agents can (not the title, contents, closing or added slides).');
}
if (code === 400) return fail(400, said ? `The agents refused the request: ${said.slice(0, 160)}` : 'The agents refused the request.');
if (code !== 200) return fail(502, `The deck agents failed (HTTP ${code || '?'})${said ? `: ${said.slice(0, 160)}` : ''}. See the execution of "RFP 60 Regenerate one slide" in n8n.`);

const spec = body && typeof body === 'object' && !Array.isArray(body) ? body : null;
if (!spec || spec.type !== 'content' || typeof spec.title !== 'string' || !Array.isArray(spec.blocks)) return fail(502, 'The deck agents did not answer with a slide.');
const warnings = (Array.isArray(spec.warnings) ? spec.warnings : []).filter(w => typeof w === 'string');
const last = warnings[warnings.length - 1] || '';
if (/slide inchangée\s*$/i.test(last)) {                         // pipeline.regenerate kept the current slide
  return /trop longue/i.test(last) ? fail(504, 'The agents took too long (over 45 s): the slide was not changed. Try again.')
    : fail(502, 'The agents could not rewrite this slide: it was not changed. Try again, or edit it by hand.');
}
// a slide the agent could not make is not saved either. Decided from the slide, not from the stage's warnings: the
// diagrams stage makes the architecture and the plan with two LLM calls and lists the failure of one on every slide
const placeholder = (warnings.find(w => /^Diapositive non générée : /.test(w)) || '').replace(/^Diapositive non générée : /, '');
const noLlm = warnings.find(w => /LLM indisponible/.test(w)) || '';      // agent 1 or 5: its one call gave nothing usable
const svg = b => { const m = /^data:image\/svg\+xml;base64,(.+)$/.exec(String(b.src || '')); return m ? Buffer.from(m[1], 'base64').toString('utf8') : ''; };
const noDiagram = spec.blocks.some(b => (b.kind === 'image' && / - À compléter<\/text>/.test(svg(b)))        // empty architecture
  || (b.kind === 'table' && (b.rows || []).some(row => /^\[TO FILL: phases/.test(String((row || [])[0])))));  // plan placeholder
if ((placeholder && !/^mock mode/.test(placeholder)) || noLlm || noDiagram) {    // mock mode (no LLM) is a test: saved
  const why = [placeholder, noLlm, ...warnings.filter(w => /à compléter\)$/.test(w))].join(' ');
  if (/quota|\b429\b/i.test(why)) return fail(503, 'The agents\' LLM is out of quota: the slide was not changed. Try again later.');
  if (noLlm) return fail(503, 'The agents\' LLM gave no usable answer (busy or down): the slide was not changed. Try again later.');
  if (placeholder) return fail(502, `The agents failed on this slide (${placeholder.slice(0, 160)}): it was not changed. Try again, or edit it by hand.`);
  return fail(502, 'The agents could not redo the diagram or plan of this slide: it was not changed. Try again, change the instruction, or edit it by hand.');
}
return [{ json: { _ok: true, spec, warnings, saveUrl: req.saveUrl } }];

// ============================================================================
// Refine Slide: Answer. The studio's answer to the slide write (POST /api/decks/<id>/slides/<n>: it validates the spec,
// lays it out with the deck's theme and saves it, exactly like its own Regenerate route) -> the interface's answer:
// 200 {status: 'ok', slideIndex, title, warnings[]} or {status: 'error', message} with a 4xx / 5xx code.
// ============================================================================
const req = $('Check request').first().json;
const ok = $('Check slide').first().json;
const r = $input.first().json || {};
const fail = (statusCode, message) => [{ json: { statusCode, _prices: false, body: { status: 'error', message } } }];

if (r.error) return fail(502, 'The proposal studio cannot be reached: the slide was not saved.');
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON: handled below */ } }
const code = Number(r.statusCode) || 0;
const said = body && typeof body === 'object' ? String(body.message || body.error || '') : '';
if (code === 401) return fail(502, 'The proposal studio refused the "Proposal Studio key" credential: the slide was not saved.');
if (code === 404) return fail(404, 'This deck is no longer in the proposal studio.');
if (code === 400 && /out of range/i.test(said)) return fail(400, `This deck has no slide ${req.slideIndex + 1} any more: open the deck again.`);
if (code === 400) {
  const why = body && Array.isArray(body.errors) && body.errors.length ? `: ${String(body.errors[0]).slice(0, 160)}` : '';
  return fail(502, `The proposal studio refused the new slide${why}. The slide was not changed.`);
}
if (code !== 200 || !body || body.status !== 'ok') return fail(502, `The proposal studio could not save the slide (HTTP ${code || '?'}${said ? `: ${said.slice(0, 120)}` : ''}).`);

// a slide that holds prices needs a new approval before export, as after the editor's own Regenerate (next nodes)
return [{ json: { statusCode: 200, _prices: !!(body.slide && body.slide.requiresApproval),
  body: { status: 'ok', slideIndex: req.slideIndex, title: ok.spec.title, warnings: ok.warnings } } }];

// ============================================================================
// Refine Slide: Reset price approval. The refined slide holds prices (requiresApproval): like the editor after its own
// Regenerate, the deck's price approval (approvals.pricing) is dropped, so the prices must be approved again before export.
// The studio's slide route keeps it, so this node reads the deck (GET /api/save/<id>, no key) and writes it back without
// the approval (POST /api/save) when one is set. Never fatal: the slide is saved already, a failure adds a warning.
// ============================================================================
const req = $('Check request').first().json;
const a = $input.first().json;
const out = { statusCode: a.statusCode, body: { ...a.body, warnings: [...(a.body.warnings || [])] } };
try {
  const h = (typeof this !== 'undefined' && this && this.helpers) || helpers;   // n8n's HTTP client (the agents use it too)
  const deck = await h.httpRequest({ method: 'GET', url: req.deckUrl, json: true, timeout: 15000 });
  // write back only the deck that was read (its id, its slides), never a partial or empty one
  if (deck && deck.id === req.deckId && Array.isArray(deck.slides) && deck.slides.length && deck.approvals && deck.approvals.pricing) {
    delete deck.approvals.pricing;
    delete deck.approvals.at;
    await h.httpRequest({ method: 'POST', url: `${req.studioUrl}/api/save`, body: deck, json: true, timeout: 15000 });
    out.body.warnings.push('The prices changed: approve them again in the editor before export.');
  }
} catch (e) {
  out.body.warnings.push('The price approval could not be reset: check the prices and approve them again in the editor.');
}
return [{ json: out }];
